with with_windows as (select id, starts_on, discount_pct, lag(discount_pct) over w_recent prev_discount_pct, lead(discount_pct) over w_recent next_discount_pct, row_number() over w_recent seq_no, avg(discount_pct) over (partition by channel order by ends_on, id rows between 6 preceding and current row) discount_pct_avg_6 from promotions window w_recent as (partition by channel order by starts_on, id)) select case when discount_pct >= 0.29 then 'PREMIUM' else 'STANDARD' end as discount_pct_tier, count(distinct id) as distinct_ids, count(*) as event_count, count(*) as event_count_2, count(*) as num_rows, grouping_id() as grouping_id from with_windows group by rollup (case when discount_pct >= 0.29 then 'PREMIUM' else 'STANDARD' end) order by event_count desc
